import * as React from 'react';

import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import CloseIcon from '@mui/icons-material/Close';
import Collapse from '@mui/material/Collapse';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import IconButton from '@mui/material/IconButton';
import Typography from '@mui/material/Typography';

import { SnackbarContent, withSnackbar } from 'notistack';

class SubscriptionBanner extends React.Component {
  state = {
    expanded: false
  }

  constructor(props) {
    super(props)
    this.toggleExpantion = this.toggleExpantion.bind(this)
    this.dismiss = this.dismiss.bind(this)
  }

  toggleExpantion() {
    this.setState({ expanded: !this.state.expanded })
  }

  dismiss() {
    this.props.closeSnackbar(this.props.id)
  }

  render() {
    return (
      <SnackbarContent ref={ this.props.forwardedRef }>
        <Card
          elevation={5}
          sx={{
            bgcolor: 'success.light',
          }}
        >
          <CardHeader
            sx={{
              py: 1,
              px: 2,
            }}
            action={
              <React.Fragment>
                <IconButton
                  onClick={ this.toggleExpantion }
                >
                  {
                    this.state.expanded ? <ExpandLessIcon/> : <ExpandMoreIcon/>
                  }
                </IconButton>
                <IconButton onClick={ this.dismiss }>
                  <CloseIcon />
                </IconButton>
              </React.Fragment>
            }
            disableTypography
            title={
              <Typography variant="subtitle1" sx={{ fontWeight: 'bold' }}>
                { `New event in subscription ${this.props.subscriptionId}` }
              </Typography>
            }
          />
          <Collapse
            in={ this.state.expanded }
            unmountOnExit
          >
            <CardContent
              sx={{
                py: 1,
                px: 2,
                '&:last-child': {
                  py: 1,
                  px: 2,
                },
                bgcolor: 'background.paper'
              }}
            >
              <Typography
                sx={{ fontWeight: 'bold', pr: 1 }}
                style={{ display: 'inline-block' }}
              >
                Subscription name:
              </Typography>
              <Typography
                style={{ display: 'inline-block' }}
              >
                { this.props.name }
              </Typography>
              <Typography
                sx={{ fontWeight: 'bold' }}
              >
                Subscription params:
              </Typography>
              <Typography
                style={{ whiteSpace: 'pre-wrap' }}
              >{
                JSON.stringify(
                  this.props.params,
                  null,
                  2
                ) || ''
              }</Typography>
            </CardContent>
          </Collapse>
          <Collapse
            in={ this.state.expanded }
            unmountOnExit
          >
            <CardContent
              sx={{
                px: 2,
                pt: 1,
                '&:last-child': {
                  pb: 0,
                },
              }}
            >
              <Typography
                sx={{ fontWeight: 'bold' }}
              >
                Event attributes:
              </Typography>
            </CardContent>
          </Collapse>
          <CardContent
            sx={{
              py: 1,
              px: 2,
              '&:last-child': {
                py: 1,
                px: 2,
              },
            }}
          >
            <Typography style={{whiteSpace: 'pre-wrap'}}>
              { JSON.stringify(this.props.eventAttributes, null, 2) || '' }
            </Typography>
          </CardContent>
        </Card>
      </SnackbarContent>
    )
  }
}

export default withSnackbar(React.forwardRef((props, ref) => (
  <SubscriptionBanner
    { ...props }
    forwardedRef={ ref }
  />
)));
