import * as React from 'react';
import Box from '@mui/material/Box';
import TextField from '@mui/material/TextField';
import MUILink from '@mui/material/Link';

class Link extends React.Component {
  state = {
    link: 'https://icq.com',
  }

  constructor(props) {
    super(props)

    this.setLink = this.setLink.bind(this)
  }

  setLink(link) {
    this.setState({ link: link })
  }

  render() {
    return (
      <Box my={1}>
        <TextField
          label="Link"
          placeholder="https://icq.com"
          fullWidth
          value={ this.state.link }
          onChange={ event => this.setLink(event.target.value) }
        />
        <Box sx={{ my: 2 }}>
          <MUILink href={this.state.link}>
            { this.state.link }
          </MUILink>
        </Box>
      </Box>
    )
  }
}

export default Link
