import React from 'react';
import ResponsiveDrawer from './ResponsiveDrawer';
import { unstable_HistoryRouter as HistoryRouter } from "react-router-dom";
import { createMemoryHistory, Action } from "history";
import { SnackbarProvider } from 'notistack';

let bridge = require('vk-teams-bridge')

class App extends React.Component {
  state = {
    canGoBack: false,
    canGoForward: false,
  }

  constructor(props) {
    super(props)

    this.stack = [ '/' ];
    this.history = createMemoryHistory({
      initialEntries: this.stack,
    });

    this.history.listen(
      ({ action, location }) => {
        this.stack[this.history.index] = location
        if (action === Action.Push) {
          this.stack = this.stack.slice(0, this.history.index + 1)
        }

        this.checkCanGoBackChanged()
      }
    )
  }

  notify(eventName) {
    bridge.send(
      eventName
    ).then(success => {
      console.info(`${eventName} ok`)
    }).catch(error => {
      console.error(`${eventName} error`, error)
    })
  }

  sendCanGoBack() {
    this.notify(this.history.index ? 'SetCanGoBack' : 'SetCanNotGoBack')
  }

  checkCanGoBackChanged() {
    let canGoBack = this.history.index > 0
    let canGoForward = this.history.index < this.stack.length - 1

    if (this.state.canGoBack !== canGoBack) {
      this.setState({ canGoBack })
      this.sendCanGoBack()
    }

    if (this.state.canGoForward !== canGoForward) {
      this.setState({ canGoForward })
    }
  }

  componentDidMount() {
    bridge.subscribe(
      'BackButtonPressed',
      () => { this.history.back() }
    ).then(success => {
      console.info('BackButtonPressed subscribed')
    }).catch(error => {
      console.error('BackButtonPressed subscription failed', error)
    })

    bridge.send(
      'LoadingCompleted',
      { ok: true }
    ).then(success => {
      console.info('LoadingCompleted success cb called')
    }).catch(error => {
      console.error('LoadingCompleted error cb called', error)
    })
  }

  render() {
    return (
      <HistoryRouter history={ this.history }>
        <SnackbarProvider maxSnack={3}>
          <ResponsiveDrawer
            canGoBack={ this.state.canGoBack }
            canGoForward={ this.state.canGoForward }
          />
        </SnackbarProvider>
      </HistoryRouter>
    );
  }
}

export default App
