import * as React from 'react';
import Box from '@mui/material/Box';
import TextField from '@mui/material/TextField';
import LoadingButton from '@mui/lab/LoadingButton';

class Action extends React.Component {
  state = {
    request_name: '',
    request_name_is_valid: false,
    request_params: '',
    request_params_are_valid: true,
    waiting_for_response: false,
    successfull_result: undefined,
    error_result: undefined,
  }

  constructor(props) {
    super(props)

    this.doAction = this.doAction.bind(this)
  }

  doAction() {
    this.props.handler(
      this.state.request_name,
      JSON.parse(this.state.request_params || null)
    ).then(success => {
      this.setState({
        waiting_for_response: false,
        successfull_result: JSON.stringify(success, null, 2) || '',
        error_result: undefined,
      })
    }).catch(error => {
      this.setState({
        waiting_for_response: false,
        successfull_result: undefined,
        error_result: JSON.stringify(error, null, 2) || '',
      })
    })

    this.setState({
      waiting_for_response: true,
      successfull_result: undefined,
      error_result: undefined,
    })
  }

  setName(name) {
    this.setState({
      waiting_for_response: false,
      successfull_result: undefined,
      error_result: undefined,
      request_name: name,
      request_name_is_valid: name !== '',
    })
  }

  setParams(params) {
    var valid = true;
    try {
      JSON.parse(params || null)
    } catch {
      valid = false
    }

    this.setState({
      waiting_for_response: false,
      successfull_result: undefined,
      error_result: undefined,
      request_params: params,
      request_params_are_valid: valid,
    })
  }

  componentDidUpdate(prevProps, prevState) {
    if (prevState.request_name !== this.state.request_name) {
      this.setState({ request_name_is_valid: this.state.request_name !== '' })
    }

    if (prevState.request_params !== this.state.request_params) {
      try {
        JSON.parse(this.state.request_params || null);
        this.setState({ request_params_are_valid: true })
      } catch {
        this.setState({ request_params_are_valid: false })
      }
    }
  }

  render() {
    return (
      <Box my={1}>
        <TextField
          label={ `${this.props.name} Name` }
          required
          fullWidth
          margin="dense"
          value={ this.state.request_name }
          onChange={ event => this.setName(event.target.value) }
          error={ !this.state.request_name_is_valid }
          disabled={ this.state.waiting_for_response }
        />
        <TextField
          label={ `${this.props.name} Params JSON (optional)` }
          fullWidth
          multiline
          minRows={5}
          margin="dense"
          value={ this.state.request_params }
          onChange={ event => this.setParams(event.target.value) }
          error={ !this.state.request_params_are_valid }
          disabled={ this.state.waiting_for_response }
        />
        <LoadingButton
          sx={{ my: 1 }}
          onClick={ this.doAction }
          loading={ this.state.waiting_for_response }
          variant="contained"
          disabled={ !this.state.request_name_is_valid || !this.state.request_params_are_valid }
        >
          { this.props.buttonName }
        </LoadingButton>
        { this.state.successfull_result !== undefined || this.state.error_result !== undefined ?
          <TextField
            fullWidth
            multiline
            readOnly
            focused
            margin="normal"
            label={ this.state.successfull_result !== undefined ? "Success" : "Error" }
            value={ this.state.successfull_result !== undefined ? this.state.successfull_result : this.state.error_result }
            color={ this.state.successfull_result !== undefined ? "success" : "error" }
          />
          : undefined
        }
      </Box>
    )
  }
}

export default Action
