import * as React from 'react';
import AppBar from '@mui/material/AppBar';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import Box from '@mui/material/Box';
import CssBaseline from '@mui/material/CssBaseline';
import Divider from '@mui/material/Divider';
import Drawer from '@mui/material/Drawer';
import IconButton from '@mui/material/IconButton';
import List from '@mui/material/List';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import MenuIcon from '@mui/icons-material/Menu';
import RefreshIcon from '@mui/icons-material/Refresh';
import SettingsEthernetIcon from '@mui/icons-material/SettingsEthernet';
import CompareArrowsIcon from '@mui/icons-material/CompareArrows';
import SubscriptionsIcon from '@mui/icons-material/Subscriptions';
import LinkIcon from '@mui/icons-material/Link';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';

import { Route, Routes, Navigate, NavLink as BaseNavLink, useLocation, useNavigate } from "react-router-dom";

import BridgeRequest from "./bridge/Request";
import BridgeSubscription from "./bridge/Subscription";
import Link from "./Link";

const NavLink = React.forwardRef(
  ({ activeClassName, activeStyle, ...props }, ref) => {
    return (
      <BaseNavLink
        ref={ref}
        {...props}
        className={({ isActive }) =>
          [
            props.className,
            isActive ? activeClassName : null,
          ]
            .filter(Boolean)
            .join(" ")
        }
        style={({ isActive }) => ({
          ...props.style,
          ...(isActive ? activeStyle : null),
        })}
      />
    );
  }
);

class ResponsiveDrawer extends React.Component {
  drawerWidth = 240;

  state = {
    location: '',
    mobileOpen: false,
  }

  constructor(props) {
    super(props);

    this.actualizeLocation = this.actualizeLocation.bind(this)
    this.handleDrawerToggle = this.handleDrawerToggle.bind(this)
    this.observer = new MutationObserver(this.actualizeLocation)
  }

  handleDrawerToggle() {
    this.setState({
      mobileOpen: !this.state.mobileOpen
    })
  }

  actualizeLocation() {
    if (this.state.location !== document.location.href) {
      this.setState({
        location: document.location.href,
      })
    }
  }

  componentDidMount() {
    this.setState({
      location: document.location.href,
    })
    this.observer.observe(document, { childList: true, subtree: true })
    window.addEventListener('hashchange', this.actualizeLocation)
    window.addEventListener('popstate', this.actualizeLocation)
  }

  componentWillUnmount() {
    this.observer.disconnect()
    window.removeEventListener('hashchange', this.actualizeLocation)
    window.removeEventListener('popstate', this.actualizeLocation)
  }

  render() {
    const drawer = (
      <div>
        <Toolbar />
        <Divider />
        <List>
          <ListItemButton end activeClassName="Mui-selected" component={NavLink} onClick={ this.handleDrawerToggle } to="/bridge">
            <ListItemIcon>
              <SettingsEthernetIcon/>
            </ListItemIcon>
            <ListItemText primary='Bridge'/>
          </ListItemButton>
          <ListItemButton end activeClassName="Mui-selected" component={NavLink} onClick={ this.handleDrawerToggle } to="/bridge/request" sx={{ pl: 4 }}>
            <ListItemIcon>
              <CompareArrowsIcon/>
            </ListItemIcon>
            <ListItemText primary='Request'/>
          </ListItemButton>
          <ListItemButton end activeClassName="Mui-selected" component={NavLink} onClick={ this.handleDrawerToggle } to="/bridge/subscription" sx={{ pl: 4 }}>
            <ListItemIcon>
              <SubscriptionsIcon/>
            </ListItemIcon>
            <ListItemText primary='Subscription'/>
          </ListItemButton>
          <ListItemButton end activeClassName="Mui-selected" component={NavLink} onClick={ this.handleDrawerToggle } to="/link">
            <ListItemIcon>
              <LinkIcon/>
            </ListItemIcon>
            <ListItemText primary='Link'/>
          </ListItemButton>
        </List>
      </div>
    );

    const container = window.document.body;

    return (
      <Box sx={{ display: 'flex' }}>
        <CssBaseline />
        <AppBar
          sx={{
            width: { sm: `calc(100% - ${this.drawerWidth}px)` },
            ml: { sm: `${this.drawerWidth}px` },
          }}
        >
          <Toolbar sx={{ flexWrap: 'wrap' }}>
            <IconButton
              color="inherit"
              edge="start"
              onClick={this.handleDrawerToggle}
              sx={{ mr: 2, display: { sm: 'none' } }}
            >
              <MenuIcon />
            </IconButton>
            <IconButton
              color="inherit"
              disabled={ !this.props.canGoBack }
              onClick={ () => this.props.navigate(-1) }
              sx={{ mr: 1 }}
            >
              <ArrowBackIcon/>
            </IconButton>
            <IconButton
              color="inherit"
              disabled={ !this.props.canGoForward }
              onClick={ () => this.props.navigate(1) }
              sx={{ mr: 1 }}
            >
              <ArrowForwardIcon/>
            </IconButton>
            <IconButton
              color="inherit"
              onClick={ () => this.props.navigate(0) }
              sx={{ mr: 1 }}
            >
              <RefreshIcon/>
            </IconButton>
            <Typography variant="h6" component="div" sx={{ overflowWrap: 'break-word', minWidth: 0 }}>
              { this.props.location.pathname }
            </Typography>
          </Toolbar>
        </AppBar>
        <Box
          component="nav"
          sx={{ width: { sm: this.drawerWidth }, flexShrink: { sm: 0 } }}
        >
          {/* The implementation can be swapped with js to avoid SEO duplication of links. */}
          <Drawer
            container={container}
            variant="temporary"
            open={this.state.mobileOpen}
            onClose={this.handleDrawerToggle}
            ModalProps={{
              keepMounted: true, // Better open performance on mobile.
            }}
            sx={{
              display: { xs: 'block', sm: 'none' },
              '& .MuiDrawer-paper': { boxSizing: 'border-box', width: this.drawerWidth },
            }}
          >
            {drawer}
          </Drawer>
          <Drawer
            variant="permanent"
            sx={{
              display: { xs: 'none', sm: 'block' },
              '& .MuiDrawer-paper': { boxSizing: 'border-box', width: this.drawerWidth },
            }}
            open
          >
            {drawer}
          </Drawer>
        </Box>
        <Box
          component="main"
          sx={{ flexGrow: 1, p: 3, width: { sm: `calc(100% - ${this.drawerWidth}px)` } }}
        >
          <Toolbar sx={{ height: '120px' }} />
          <Routes>
            <Route path='bridge'>
              <Route index element={ <Navigate to="request" replace/> }/>
              <Route path='request' element={ <BridgeRequest/> }/>
              <Route path='subscription' element={ <BridgeSubscription/> }/>
              <Route path='*' element={ <Navigate to="request" replace/> }/>
            </Route>
            <Route path='link' element={ <Link/> }/>
            <Route path='*' element={ <Navigate to="bridge" replace/> }/>
          </Routes>
        </Box>
      </Box>
    );
  }
}

export default function ResponsiveDrawerWithRouter(props) {
  return (
    <ResponsiveDrawer
      {...props}
      location={ useLocation() }
      navigate={ useNavigate() }
    />
  )
}
